package com.bridger.momentum;
import java.io.*;
import java.nio.file.*;
import java.net.*;
import java.security.*;
import java.util.*;
import java.util.zip.*;
import com.google.gson.*;

/** Read-only 26.2 asset import. No Minecraft assets are bundled with BridgeTap. */
public final class ModernBlockCatalog {
 public static final Path FILE=Paths.get("config/bridgetap/modern-blocks/client-26.2.jar");
 public final Path file;private final List<String> blocks=new ArrayList<>();private final Map<String,JsonObject> models=new HashMap<>();
 public static final class Model {public final JsonObject json;public final int x,y;public final boolean fallback;Model(JsonObject json,int x,int y,boolean fallback){this.json=json;this.x=x;this.y=y;this.fallback=fallback;}}
 public ModernBlockCatalog(Path file)throws IOException{this.file=file.toAbsolutePath();try(ZipFile zip=new ZipFile(file.toFile())){JsonObject version=object(zip,"version.json");if(!"26.2".equals(version.get("id").getAsString()))throw new IOException("Choose the Minecraft Java 26.2 client JAR");Enumeration<? extends ZipEntry> entries=zip.entries();while(entries.hasMoreElements()){String n=entries.nextElement().getName();if(n.startsWith("assets/minecraft/blockstates/")&&n.endsWith(".json")){String id=n.substring(29,n.length()-5);if(id.matches("[a-z0-9_/]+"))blocks.add("modern:"+id);}}}if(blocks.isEmpty())throw new IOException("No block models found");Collections.sort(blocks);}
 public List<String> blocks(){return Collections.unmodifiableList(blocks);}
 private static JsonObject object(ZipFile zip,String entry)throws IOException{ZipEntry e=zip.getEntry(entry);if(e==null||e.getSize()>1024*1024)throw new IOException("Missing or oversized asset: "+entry);try(InputStream in=zip.getInputStream(e)){return new JsonParser().parse(new InputStreamReader(in,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();}catch(RuntimeException ex){throw new IOException("Invalid model JSON: "+entry,ex);}}
 private static String asset(String id){String[] p=id.split(":",2);String ns=p.length==2?p[0]:"minecraft",path=p.length==2?p[1]:p[0];if(!ns.matches("[a-z0-9_]+")||!path.matches("[a-z0-9_/]+")||path.contains(".."))throw new IllegalArgumentException("Invalid asset path");return "assets/"+ns+"/models/"+path+".json";}
 private JsonObject resolve(ZipFile zip,String id,Set<String> seen)throws IOException{if(seen.size()>30||!seen.add(id))throw new IOException("Cyclic model parent");if(models.containsKey(id))return copy(models.get(id));JsonObject child=object(zip,asset(id)),result=new JsonObject();if(child.has("parent")&&!child.get("parent").getAsString().contains("builtin/"))result=resolve(zip,child.get("parent").getAsString(),seen);JsonObject textures=result.has("textures")?result.getAsJsonObject("textures"):new JsonObject();if(child.has("textures"))for(Map.Entry<String,JsonElement> e:child.getAsJsonObject("textures").entrySet())textures.add(e.getKey(),e.getValue());for(Map.Entry<String,JsonElement> e:child.entrySet())if(!e.getKey().equals("parent")&&!e.getKey().equals("textures"))result.add(e.getKey(),e.getValue());result.add("textures",textures);result.remove("parent");result.remove("display");models.put(id,copy(result));return result;}
 private static JsonObject copy(JsonObject value){return new JsonParser().parse(value.toString()).getAsJsonObject();}
 private static JsonObject first(JsonElement value){return value.isJsonArray()?value.getAsJsonArray().get(0).getAsJsonObject():value.getAsJsonObject();}
 private static boolean matches(JsonObject when,Map<String,String> state){for(Map.Entry<String,JsonElement> e:when.entrySet()){if(e.getKey().equals("OR")||e.getKey().equals("AND")){boolean result=e.getKey().equals("AND");for(JsonElement term:e.getValue().getAsJsonArray()){boolean match=matches(term.getAsJsonObject(),state);result=e.getKey().equals("AND")?result&&match:result||match;}if(!result)return false;}else{String expected=e.getValue().getAsString();String actual=state.get(e.getKey());if(actual==null){state.put(e.getKey(),expected.split("\\|")[0]);continue;}if(!Arrays.asList(expected.split("\\|")).contains(actual))return false;}}return true;}
 public List<Model> models(String key)throws IOException{if(!blocks.contains(key))throw new IOException("Unknown modern block");String name=key.substring(7);try(ZipFile zip=new ZipFile(file.toFile())){JsonObject state=object(zip,"assets/minecraft/blockstates/"+name+".json");List<JsonObject> selected=new ArrayList<>();Map<String,String> properties=new HashMap<>();if(state.has("variants")){Map.Entry<String,JsonElement> choice=state.getAsJsonObject("variants").entrySet().iterator().next();for(String p:choice.getKey().split(",")){String[] pair=p.split("=",2);if(pair.length==2)properties.put(pair[0],pair[1]);}selected.add(first(choice.getValue()));}else if(state.has("multipart")){for(JsonElement p:state.getAsJsonArray("multipart")){JsonObject part=p.getAsJsonObject();if(!part.has("when")||matches(part.getAsJsonObject("when"),properties))selected.add(first(part.get("apply")));}}
  List<Model> result=new ArrayList<>();for(JsonObject selection:selected){JsonObject model;boolean fallback=false;try{model=resolve(zip,selection.get("model").getAsString(),new HashSet<>());}catch(IOException|RuntimeException ex){model=new JsonObject();fallback=true;}if(!model.has("elements")||model.getAsJsonArray("elements").size()==0){model=cube(zip,model,name);fallback=true;}for(JsonElement element:model.getAsJsonArray("elements")){JsonObject part=element.getAsJsonObject();if(part.has("rotation")){JsonObject rotation=part.getAsJsonObject("rotation");if(rotation.has("angle")&&Math.abs(rotation.get("angle").getAsDouble())<0.001)rotation.addProperty("angle",0);}}JsonObject textures=model.getAsJsonObject("textures");for(Map.Entry<String,JsonElement> t:new ArrayList<>(textures.entrySet())){String value=t.getValue().isJsonObject()?t.getValue().getAsJsonObject().get("sprite").getAsString():t.getValue().getAsString();if(!value.startsWith("#")){String[] p=value.split(":",2);String ns=p.length==2?p[0]:"minecraft",path=p.length==2?p[1]:p[0];if(zip.getEntry("assets/"+ns+"/textures/"+path+".png")==null){ns="minecraft";path="block/stone";fallback=true;}textures.addProperty(t.getKey(),"bridgetap:modern/"+ns+"/"+path);}}result.add(new Model(model,selection.has("x")?selection.get("x").getAsInt():0,selection.has("y")?selection.get("y").getAsInt():0,fallback));}return result;}}
 private static JsonObject cube(ZipFile zip,JsonObject original,String name){String texture="minecraft:block/"+name;if(zip.getEntry("assets/minecraft/textures/block/"+name+".png")==null){texture="minecraft:block/stone";if(original.has("textures"))for(Map.Entry<String,JsonElement> e:original.getAsJsonObject("textures").entrySet())if(!e.getValue().getAsString().startsWith("#")){texture=e.getValue().getAsString();break;}}JsonObject result=new JsonParser().parse("{\"textures\":{},\"elements\":[{\"from\":[0,0,0],\"to\":[16,16,16],\"faces\":{}}]}").getAsJsonObject();result.getAsJsonObject("textures").addProperty("all",texture);result.getAsJsonObject("textures").addProperty("particle","#all");JsonObject faces=result.getAsJsonArray("elements").get(0).getAsJsonObject().getAsJsonObject("faces");for(String direction:new String[]{"down","up","north","south","west","east"}){JsonObject face=new JsonObject();face.addProperty("texture","#all");faces.add(direction,face);}return result;}
 public static Set<String> textures(List<Model> models){Set<String> result=new HashSet<>();for(Model m:models)for(Map.Entry<String,JsonElement> t:m.json.getAsJsonObject("textures").entrySet())if(!t.getValue().getAsString().startsWith("#"))result.add(t.getValue().getAsString());return result;}
 /** The legacy resolver rejects alias chains in one flattened model (#side -> #all).
  * Resolve them before parsing, including absolute face references. */
 public static String texture(Model model,String reference){Set<String> seen=new HashSet<>();JsonObject map=model.json.getAsJsonObject("textures");String value=map.has(reference)?"#"+reference:reference;while(value.startsWith("#")){if(!seen.add(value))return "missingno";JsonElement next=map.get(value.substring(1));if(next==null)return "missingno";value=next.getAsString();}return value;}
 public byte[] resource(String namespace,String path)throws IOException{if(!namespace.equals("bridgetap")||!path.startsWith("textures/modern/")||path.contains(".."))throw new FileNotFoundException(path);String remainder=path.substring(16);int slash=remainder.indexOf('/');if(slash<1)throw new FileNotFoundException(path);String entry="assets/"+remainder.substring(0,slash)+"/textures/"+remainder.substring(slash+1);try(ZipFile zip=new ZipFile(file.toFile())){ZipEntry e=zip.getEntry(entry);if(e==null||e.getSize()>4*1024*1024)throw new FileNotFoundException(path);try(InputStream in=zip.getInputStream(e)){return UpdateSource.read(in,4*1024*1024);}}}
 private static HttpURLConnection connection(String address)throws IOException{URL u=new URL(address);if(!u.getProtocol().equals("https")||!(u.getHost().equals("piston-meta.mojang.com")||u.getHost().equals("piston-data.mojang.com")||u.getHost().equals("launchermeta.mojang.com")))throw new IOException("Unexpected Minecraft download host");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","BridgeTap/1.8.0 (Minecraft resource import)");c.setConnectTimeout(10000);c.setReadTimeout(20000);return c;}
 private static byte[] get(String url,int max)throws IOException{HttpURLConnection c=connection(url);c.setRequestProperty("Range","bytes=0-"+(max-1));try(InputStream in=c.getInputStream()){return UpdateSource.read(in,max);}finally{c.disconnect();}}
 private static byte[] client(String url,int size,java.util.function.IntConsumer progress)throws IOException{
  if(size<1||size>96*1024*1024)throw new IOException("Minecraft resource archive exceeds size limit");ByteArrayOutputStream bytes=new ByteArrayOutputStream(size);
  while(bytes.size()<size){int start=bytes.size(),end=Math.min(size-1,start+1024*1024-1);IOException error=null;
   for(int attempt=0;attempt<3;attempt++){HttpURLConnection c=connection(url);c.setRequestProperty("Range","bytes="+start+"-"+end);try{int code=c.getResponseCode();
    if(code==200&&start==0){try(InputStream in=c.getInputStream()){byte[] full=UpdateSource.read(in,size);if(full.length!=size)throw new IOException("Incomplete Minecraft resource download");progress.accept(100);return full;}}
    if(code!=206||!("bytes "+start+"-"+end+"/"+size).equals(c.getHeaderField("Content-Range")))throw new IOException("Minecraft server returned an unexpected download range");
    try(InputStream in=c.getInputStream()){byte[] chunk=UpdateSource.read(in,end-start+1);if(chunk.length!=end-start+1)throw new IOException("Incomplete Minecraft resource chunk");bytes.write(chunk);}error=null;break;
   }catch(IOException ex){error=ex;}finally{c.disconnect();}}
   if(error!=null)throw error;progress.accept((int)(bytes.size()*100L/size));
  }return bytes.toByteArray();
 }
 public static ModernBlockCatalog importFile(Path source)throws IOException{if(!Files.isRegularFile(source)||Files.size(source)>96*1024*1024)throw new IOException("Choose a Minecraft 26.2 client JAR smaller than 96 MiB");new ModernBlockCatalog(source);Files.createDirectories(FILE.getParent());if(!source.toAbsolutePath().normalize().equals(FILE.toAbsolutePath().normalize())){Path temp=Files.createTempFile(FILE.getParent(),"client-",".jar");try{Files.copy(source,temp,StandardCopyOption.REPLACE_EXISTING);Files.move(temp,FILE,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(temp);}}return new ModernBlockCatalog(FILE);}
 public static ModernBlockCatalog download()throws Exception{return download(percent->{});}
 public static ModernBlockCatalog download(java.util.function.IntConsumer progress)throws Exception{JsonObject manifest=UpdateSource.json(get("https://piston-meta.mojang.com/mc/game/version_manifest_v2.json",4*1024*1024));String metadata=null;for(JsonElement v:manifest.getAsJsonArray("versions"))if(v.getAsJsonObject().get("id").getAsString().equals("26.2"))metadata=v.getAsJsonObject().get("url").getAsString();if(metadata==null)throw new IOException("Minecraft 26.2 is unavailable");JsonObject asset=UpdateSource.json(get(metadata,4*1024*1024)).getAsJsonObject("downloads").getAsJsonObject("client");byte[] bytes=client(asset.get("url").getAsString(),asset.get("size").getAsInt(),progress);MessageDigest digest=MessageDigest.getInstance("SHA-1");StringBuilder hash=new StringBuilder();for(byte b:digest.digest(bytes))hash.append(String.format(Locale.ROOT,"%02x",b&255));if(!hash.toString().equals(asset.get("sha1").getAsString())||bytes.length!=asset.get("size").getAsInt())throw new IOException("Minecraft resource download checksum mismatch");Files.createDirectories(FILE.getParent());Path temp=Files.createTempFile(FILE.getParent(),"client-",".jar");try{Files.write(temp,bytes);new ModernBlockCatalog(temp);Files.move(temp,FILE,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(temp);}return new ModernBlockCatalog(FILE);}
}
